using System;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Windows.Forms;
static class AnimationRenderingTests {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();Program.TestMode=true;float width;int before=MotionPaint.TextPathBuildCount;using(var first=MotionPaint.TextPath("Кэш контуров",20,-1,out width)){var bounds=first.GetBounds();first.Translate(100,100);using(var second=MotionPaint.TextPath("Кэш контуров",20,-1,out width)){Check(second.GetBounds()==bounds,"cached path clones are independent");}}Check(MotionPaint.TextPathBuildCount==before+1,"repeated text reuses vector geometry");
 using(var form=new Form{Size=new Size(900,500),StartPosition=FormStartPosition.Manual,Location=new Point(-2500,-1800)}){var actions=Theme.Flow();actions.Controls.Add(Theme.Button("Запустить",()=>{}));var stage=new StateStage(Theme.Label("",10),actions){Dock=DockStyle.Fill};form.Controls.Add(stage);stage.Present("stopped");form.Show();Application.DoEvents();var word=(TrackedWord)typeof(StateStage).GetField("word",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(stage);using(var b=new Bitmap(stage.Width,stage.Height)){stage.DrawToBitmap(b,stage.ClientRectangle);int builds=word.PaintCacheBuilds;stage.DrawToBitmap(b,stage.ClientRectangle);Check(word.PaintCacheBuilds==builds,"settled word reuses raster cache");stage.Present("running");stage.DrawToBitmap(b,stage.ClientRectangle);Check(word.Word=="RUNNING"&&word.PaintCacheBuilds>builds,"state transition invalidates stale text");}
 stage.Context("first","4096 MB","4");stage.Present("stopped");int generation=word.AnimationGeneration;stage.Context("second","4096 MB","4");stage.Present("stopped");Check(word.AnimationGeneration==generation+1,"selecting another stopped machine replays its word animation");stage.Context("second","8192 MB","8");stage.Present("stopped");Check(word.AnimationGeneration==generation+1,"polling the selected machine does not restart the animation");stage.Context("first","4096 MB","4");stage.Present("stopped");Check(word.AnimationGeneration==generation+2,"returning to the first stopped machine replays again");
 Program.TestMode=false;stage.Present("paused");var until=DateTime.UtcNow.AddSeconds(2);while(DateTime.UtcNow<until){Application.DoEvents();Thread.Sleep(10);}Check(!AnimationClock.Running&&AnimationClock.ActiveCount==0,"idle state stops shared animation clock");form.Close();}
 File.WriteAllText(args[0],"PASS: bounded geometry cache, independent path clones, settled raster reuse, state invalidation, idle timer stopped");return 0;
 }catch(Exception e){File.WriteAllText(args[0],e.ToString());return 1;}}
}
static class GraphicsPathExtension { public static void Translate(this System.Drawing.Drawing2D.GraphicsPath path,float x,float y){using(var m=new System.Drawing.Drawing2D.Matrix()){m.Translate(x,y);path.Transform(m);}}}
